	"m:algebra (1 + i)^2\n"
	"m:algebra (1 + i)^4\n"
	"m:algebra (1 + i)^8\n"
	"# Euler's formula: e^(i pi) is -1 (the tiny error shows as an approxim"
	"ation).\n"
	"m:algebra exp(i*pi)\n"
	"m:algebra exp(i*pi/2)\n";

static const char text_complex_quadratic [] =
	"# A quadratic with complex roots\n"
	"# x^2 + 2x + 5 = 0 has no real root, but two complex ones that are exa"
	"ct.\n"
	"# The discriminant b^2 - 4ac is negative, so the real solve finds noth"
	"ing:\n"
	"m:algebra f(x) = x^2 + 2x + 5\n"
	"m:algebra d = 2^2 - 4*1*5\n"
	"m:algebra solve(f(x), x)\n"
	"# The square root of a negative number is a complex number, written wi"
	"th the unit i (i*i is -1):\n"
	"m:algebra sqrt(d)\n"
	"m:algebra i*i\n"
	"# The quadratic formula gives the two roots:\n"
	"m:algebra r1 = (-2 + sqrt(d))/2\n"
	"m:algebra r2 = (-2 - sqrt(d))/2\n"
	"# They are conjugates of each other, and they satisfy the equation:\n"
	"m:algebra conj(r1)\n"
	"m:algebra f(r1)\n"
	"m:algebra f(r2)\n"
	"# Their sum is -b/a and their product c/a (Vieta):\n"
	"m:algebra r1 + r2\n"
	"m:algebra r1*r2\n"
	"# The modulus (the distance from 0) is exact when the squares add up t"
	"o a square:\n"
	"m:algebra abs(r1)\n"
	"m:algebra abs(3 + 4i)\n";

static const char text_lambda_church_arithmetic [] =
	"# Arithmetic with nothing but functions\n"
	"# In the lambda calculus a number is a function that applies f n times"
	". Everything else is built from that.\n"
	"# The successor, addition and multiplication of Church numerals:\n"
	"m:lambda succ = \316\273n f x. f (n f x)\n"
	"m:lambda plus = \316\273m n f x. m f (n f x)\n"
	"m:lambda mult = \316\273m n f. m (n f)\n"
	"# Two is a function that applies f twice. Add one:\n"
	"m:lambda succ 2\n"
	"# 2 + 3 is the numeral 5 (apply f five times):\n"
	"m:lambda plus 2 3\n"
	"# 3 * 4 is the numeral 12:\n"
	"m:lambda mult 3 4\n"
	"# Booleans are functions that choose:\n"
	"m:lambda true = \316\273a b. a\n"
	"m:lambda false = \316\273a b. b\n"
	"m:lambda and = \316\273p q. p q p\n"
	"m:lambda and true false\n"
	"# F3 on a line shows every beta step of the reduction:\n"
	"m:lambda mult 2 2\n";

static const char text_linalg_least_squares [] =
	"# A least squares line\n"
	"# Fit y = a + b t to four measurements with the normal equations.\n"
	"# Measurements: the times t and the values y.\n"
	"m:algebra X = [[1, 0], [1, 1], [1, 2], [1, 3]]\n"
	"m:algebra y = [1, 3, 4, 8]\n"
	"# The line a + b t that is closest to the points solves  X^T X c = X^T"
	" y:\n"
	"m:algebra N = transpose(X)*X\n"
	"m:algebra r = transpose(X)*y\n"
	"m:algebra c = solve(N, r)\n"
	"# The first entry is a = 7/10 and the second is b = 11/5: the line is "
	"y = 7/10 + 11/5 t.\n"
	"# The fitted values and the residuals (the error that is left):\n"
	"m:algebra X*c\n"
	"m:algebra y - X*c\n"
	"# The residuals are perpendicular to the columns of X, so X^T times th"
	"em is zero:\n"
	"m:algebra transpose(X)*(y - X*c)\n";

static const char text_linalg_linear_system [] =
	"# A linear system\n"
	"# Solve three equations in three unknowns with a matrix, and check the"
	" answer.\n"
	"# 2x + y - z = 8,  -3x - y + 2z = -11,  -2x + y + 2z = -3\n"
	"m:algebra A = [[2, 1, -1], [-3, -1, 2], [-2, 1, 2]]\n"
	"m:algebra b = [8, -11, -3]\n"
	"# The system has one solution when the determinant is not zero:\n"
	"m:algebra det(A)\n"
	"m:algebra x = solve(A, b)\n"
	"# Check that A x is b:\n"
	"m:algebra A*x\n"
	"# The same with the inverse (F3 on this line shows the row reduction):\n"
	"m:algebra inv(A)*b\n"
	"m:algebra rank(A)\n"
	"# The reduced row echelon form of A with b beside it is where the answ"
	"er is read off:\n"
	"m:algebra rref([[2, 1, -1, 8], [-3, -1, 2, -11], [-2, 1, 2, -3]])\n";

static const char text_linalg_rotations [] =
	"# Rotations as matrices\n"
	"# A rotation matrix turns a vector and keeps its length. With cos = 3/"
	"5 and sin = 4/5 everything is exact.\n"
	"m:algebra R = [[3/5, -4/5], [4/5, 3/5]]\n"
	"m:algebra v = [1, 0]\n"
	"# Rotate the vector:\n"
	"m:algebra R*v\n"
	"# Its length is the same:\n"
	"m:algebra norm(R*v)\n"
	"# A rotation is orthogonal: the transpose is the inverse, and the dete"
	"rminant is 1.\n"
	"m:algebra transpose(R)*R\n"
	"m:algebra det(R)\n"
	"# Two rotations in a row are one rotation by the sum of the angles:\n"
	"m:algebra R*R\n"
	"# Rotating back with the transpose gives the vector again:\n"
	"m:algebra transpose(R)*(R*v)\n";

static const char text_logic_minimise_circuit [] =
	"# Simplifying a logic circuit\n"
	"# A circuit is a boolean expression. matlog finds the smallest sum of "
	"products and a truth table checks it.\n"
	"m:boolean f = (a & b) | (a & ~b) | (~a & b)\n"
	"# The expression is the same as a OR b. The result above is the minima"
	"l form.\n"
	"m:boolean table a | b\n"
	"# De Morgan: not (a and b) is (not a) or (not b). Two expressions are "
	"equal when == gives true:\n"
	"m:boolean ~(a & b) == (~a | ~b)\n"
	"# Exclusive or built from and, or and not, and its truth table:\n"
	"m:boolean table (a | b) & ~(a & b)\n"
	"# A circuit with a redundant gate: the term (a & b) is covered by a.\n"
	"m:boolean a | (a & b)\n"
	"# A tautology and a contradiction:\n"
	"m:boolean a | ~a\n"
	"m:boolean a & ~a\n";

static const char text_quat_rotation [] =
	"# Rotating a vector with a quaternion\n"
	"# A quaternion q turns a 3D vector v into q v q^-1. With exact numbers"
	" the quarter turns are exact.\n"
	"# The units i, j and k multiply like the axes: i j = k, j k = i, k i ="
	" j, and j i = -k.\n"
	"m:algebra i*j\n"
	"m:algebra j*i\n"
	"m:algebra j*k\n"
	"m:algebra k*k\n"
	"# The quaternion 1 + k turns by a quarter turn about the z axis (it ha"
	"s the angle 90 degrees; the length does not matter, rotate divides it "
	"out).\n"
	"m:algebra qz = 1 + k\n"
	"m:algebra rotate(qz, [1, 0, 0])\n"
	"m:algebra rotate(qz, [0, 1, 0])\n"
	"m:algebra rotate(qz, [0, 0, 1])\n"
	"# 1 + i is a quarter turn about x:\n"
	"m:algebra qx = 1 + i\n"
	"m:algebra rotate(qx, [0, 1, 0])\n"
	"# Two rotations in a row are one quaternion: the product, with the sec"
	"ond rotation on the left.\n"
	"m:algebra q = qx*qz\n"
	"m:algebra rotate(q, [1, 0, 0])\n"
	"m:algebra rotate(qx, rotate(qz, [1, 0, 0]))\n"
	"# The order matters: turn about x first, then about z gives another re"
	"sult.\n"
	"m:algebra rotate(qz*qx, [1, 0, 0])\n"
	"# A quaternion has a conjugate, a norm and an inverse (the opposite tu"
	"rn):\n"
	"m:algebra conj(q)\n"
	"m:algebra abs(q)\n"
	"m:algebra 1/q\n"
	"m:algebra q*(1/q)\n";

static const char text_robotics_two_link_arm [] =
	"# A robot arm with two links\n"
	"# Forward and inverse kinematics of a planar arm. With rational sines "
	"and cosines the whole computation is exact.\n"
	"# A joint is a rotation by an angle, given by its cosine and sine:\n"
	"m:algebra rot(c, s) = [[c, -s], [s, c]]\n"
	"# Two links of length 5. The first joint turns by (3/5, 4/5), the seco"
	"nd by (3/5, 4/5) more:\n"
	"m:algebra l1 = 5\n"
	"m:algebra l2 = 5\n"
	"m:algebra R1 = rot(3/5, 4/5)\n"
	"m:algebra R2 = rot(3/5, 4/5)\n"
	"# Forward kinematics: the hand is link 1 turned by R1, plus link 2 tur"
	"ned by R1 R2.\n"
	"m:algebra p = R1*[l1, 0] + R1*R2*[l2, 0]\n"
	"# Inverse kinematics: given only the hand position p, find the joint a"
	"ngles.\n"
	"# The law of cosines gives the second joint from the distance to the h"
	"and:\n"
	"m:algebra c2 = (dot(p, p) - l1^2 - l2^2)/(2*l1*l2)\n"
	"m:algebra s2 = sqrt(1 - c2^2)\n"
	"# (The other sign of s2 is the elbow bent the other way.) The first li"
	"nk plus the turned second link is a vector w = (l1 + l2 c2, l2 s2) tha"
	"t R1 turns into p:\n"
	"m:algebra w = [l1 + l2*c2, l2*s2]\n"
	"# R1 = [[c1, -s1], [s1, c1]] solves  [[wx, -wy], [wy, wx]] [c1, s1] = "
	"p\n"
	"m:algebra cs1 = solve([[l1 + l2*c2, -l2*s2], [l2*s2, l1 + l2*c2]], p)\n"
	"# The answer (c1, s1) = (3/5, 4/5) is the first joint we started with."
	" Check the forward kinematics:\n"
	"m:algebra rot(3/5, 4/5)*[l1, 0] + rot(3/5, 4/5)*rot(c2, s2)*[l2, 0]\n"
	"# With angles instead of cosines and sines the same formulas use acos "
	"and atan:\n"
	"m:algebra q2 = acos(3/5)\n"
	"m:algebra q1 = atan(44/8) - atan(5*sin(q2)/(5 + 5*cos(q2)))\n";

static const char text_stats_coin_and_bell_curve [] =
	"# Coins and the bell curve\n"
	"# The chance of heads in ten tosses, and how the normal curve compares"
	".\n"
	"# The number of ways to choose 3 of 10 tosses to be heads:\n"
	"m:algebra binomial(10, 3)\n"
	"# The chance of exactly 3 heads in 10 fair tosses is binomial_pdf(n, k"
	", p), exact:\n"
	"m:algebra binomial_pdf(10, 3, 1/2)\n"
	"# Of at most 3 heads: add the chances of 0, 1, 2 and 3 heads.\n"
	"m:algebra binomial_pdf(10, 0, 1/2) + binomial_pdf(10, 1, 1/2) + binomi"
	"al_pdf(10, 2, 1/2) + binomial_pdf(10, 3, 1/2)\n"
	"# For many tosses the normal curve with the same mean n p and spread s"
	"qrt(n p (1 - p)) is close. For 100 tosses, the chance of at most 45 he"
	"ads:\n"
	"m:algebra normal_cdf(45.5, 50, 5)\n"
	"# The value below which 95 percent of a normal variable falls (mean 10"
	"0, deviation 15):\n"
	"m:algebra normal_inv(0.95, 100, 15)\n"
	"# The height of the bell at its centre:\n"
	"m:algebra normal_pdf(0, 0, 1)\n"
	"# Events that happen at a rate, like 3 calls an hour: the chance of ex"
	"actly 2 calls in an hour\n"
	"m:algebra poisson_pdf(2, 3)\n";

static const char text_stats_describe_data [] =
	"# Describing a list of numbers\n"
	"# The mean, the median, the spread and a histogram of eight exam score"
	"s, all exact.\n"
	"# Eight scores. A list is written in brackets:\n"
	"m:algebra scores = [52, 61, 61, 68, 70, 75, 83, 90]\n"
	"# The centre of the data: the mean is the sum divided by the count, th"
	"e median is the middle value, the mode the most frequent.\n"
	"m:algebra mean(scores)\n"
	"m:algebra median(scores)\n"
	"m:algebra mode(scores)\n"
	"# The spread: the sample variance divides by n - 1, the population one"
	" by n. The standard deviation is the square root, exact when the varia"
	"nce is a perfect square.\n"
	"m:algebra var(scores)\n"
	"m:algebra std(scores)\n"
	"m:algebra pvar(scores)\n"
	"# Quartiles cut the sorted data in four, the interquartile range is th"
	"e middle half:\n"
	"m:algebra quantile(scores, 1/4)\n"
	"m:algebra quantile(scores, 3/4)\n"
	"m:algebra iqr(scores)\n"
	"# How many scores are in each of four equal bins between the smallest "
	"and the largest:\n"
	"m:algebra histogram(scores, 4)\n"
	"# A z-score says how many standard deviations a value is from the mean"
	":\n"
	"m:algebra zscore(90, mean(scores), std(scores))\n";

static const char text_stats_fit_a_line [] =
	"# Fitting a line to data\n"
	"# Hours of study against the score: the slope, the intercept, the corr"
	"elation and a prediction.\n"
	"# Hours studied (x) and the score (y) of six students:\n"
	"m:algebra hours = [1, 2, 3, 4, 5, 6]\n"
	"m:algebra score = [48, 55, 59, 68, 70, 80]\n"
	"# The line y = a + b x that fits best (least squares): the vector is ["
	"a, b].\n"
	"m:algebra fit = linfit(hours, score)\n"
	"# How well the line explains the scores: r squared is the share of the"
	" spread it accounts for.\n"
	"m:algebra rsq(hours, score)\n"
	"m:algebra corr(hours, score)\n"
	"# The prediction for 7 hours is a + b * 7 (with the two numbers of the"
	" vector):\n"
	"m:algebra 629/15 + 214/35 * 7\n"
	"# A parabola fits closer (the vector is [c0, c1, c2] of c0 + c1 x + c2"
	" x^2):\n"
	"m:algebra polyfit(hours, score, 2)\n"
	"# For any matrix of unknowns use lstsq: here the same line from the de"
	"sign matrix.\n"
	"m:algebra A = [[1, 1], [1, 2], [1, 3], [1, 4], [1, 5], [1, 6]]\n"
	"m:algebra lstsq(A, score)\n";

static const char text_stats_plot_your_data [] =
	"# Plot your data\n"
	"# A plot is a value: the line shows a summary, F7 on it draws the pict"
	"ure in the panel.\n"
	"# Heights of ten plants in centimetres:\n"
	"m:algebra heights = [12, 15, 14, 10, 18, 15, 16, 13, 15, 17]\n"
	"# How the heights spread over four bins (switch it on with F7 and look"
	" at the panel):\n"
	"m:algebra hist(heights, 4)\n"
	"# Days since planting, and a straight line fitted to the heights:\n"
	"m:algebra days = range(1, 9)\n"
	"m:algebra growth = [2, 4, 5, 7, 9, 10, 12, 13, 15]\n"
	"# The points themselves:\n"
	"m:algebra scatter(days, growth)\n"
	"# The same points joined, to follow the trend:\n"
	"m:algebra plot(days, growth)\n"
	"# The fitted line gives the slope and the intercept:\n"
	"m:algebra linfit(days, growth)\n";

static const char text_units_kinetic_energy [] =
	"# Units in a physics problem\n"
	"# A car of 1200 kg drives at 90 km/h. How much energy does it have, an"
	"d how far does it travel in 20 s?\n"
	"# The mass and the speed, with their units:\n"
	"m:algebra mass = 1200 kg\n"
	"m:algebra v = 90 km/h\n"
	"# Convert the speed to SI units:\n"
	"m:algebra v to m/s\n"
	"# The kinetic energy is mass v^2 / 2. The units multiply out by themse"
	"lves:\n"
	"m:algebra mass*(v to m/s)^2/2\n"
	"# In kilojoules:\n"
	"m:algebra mass*(v to m/s)^2/2 to kJ\n"
	"# The distance in 20 seconds:\n"
	"m:algebra (v to m/s)*20 s\n"
	"# Lengths in different units add up (the sum is in metres), and to con"
	"verts back:\n"
	"m:algebra 5 km + 300 m\n"
	"m:algebra 5300 m to km\n"
	"# Time to stop with a deceleration of 8 m/s^2 from this speed:\n"
	"m:algebra (v to m/s)/(8 m/s^2)\n";

